BlockIO InterpreterSetQuery::execute()
{
    const auto & ast = query_ptr->as<ASTSetQuery &>();
    /// Resolve query parameters used as setting values, e.g. `SET max_threads = {threads:UInt64}`.
    /// Work on a copy so the original AST keeps the placeholders: they are still needed by the
    /// old-server compatibility rewrite in ClientBase::processOrdinaryQuery.
    SettingsChanges changes = ast.changes;
    replaceQueryParametersInSettingsChanges(changes, getContext()->getQueryParameters());
    /// A session-wide value would also detach the `SET` that turns it back off,
    /// which is likely to cause confusion.
    if (changes.tryGet("run_query_in_background"))
        throw Exception(ErrorCodes::BAD_ARGUMENTS,
            "run_query_in_background cannot be changed with SET, because it must be requested per query. "
            "Pass it as a query setting, or set it at the user or profile level");
    /// Pass as const on purpose: the non-const checkSettingsConstraints overload rewrites the
    /// changes (dropping no-op changes), which would lose the "changed" flag for a setting
    /// explicitly set to its current value. The original code applies const `ast.changes`.
    getContext()->checkSettingsConstraints(std::as_const(changes), SettingSource::QUERY);
    /// Checked before anything is applied, so that a violation leaves the whole statement without effect.
    getContext()->checkSettingsConstraintsForSettingsReset(ast.default_settings, changes, SettingSource::QUERY);
    auto session_context = getContext()->getSessionContext();
    session_context->applySettingsChanges(changes);
    session_context->addQueryParameters(NameToNameMap{ast.query_parameters.begin(), ast.query_parameters.end()});
    session_context->resetSettingsToDefaultValue(ast.default_settings);
    return {};
}

void InterpreterSetQuery::executeForCurrentContext(bool ignore_setting_constraints)
{
    const auto & ast = query_ptr->as<ASTSetQuery &>();
    /// Resolve query parameters used as setting values, e.g. `SELECT ... SETTINGS max_threads = {threads:UInt64}`.
    /// Work on a copy so the original AST keeps the placeholders (see the note in execute()).
    SettingsChanges changes = ast.changes;
    replaceQueryParametersInSettingsChanges(changes, getContext()->getQueryParameters());
    /// const on purpose - see the note in execute().
    if (!ignore_setting_constraints)
    {
        getContext()->checkSettingsConstraints(std::as_const(changes), SettingSource::QUERY);
        getContext()->checkSettingsConstraintsForSettingsReset(ast.default_settings, changes, SettingSource::QUERY);
        rejectHTTPOnlyConstructionSettings(ast);
    }
    getContext()->applySettingsChanges(changes);
    getContext()->resetSettingsToDefaultValue(ast.default_settings);
}

bool ParserSetQuery::parseNameValuePairWithParameterOrDefault(
    SettingChange & change, String & default_settings, ParserSetQuery::Parameter & parameter, IParser::Pos & pos, Expected & expected, bool enable_shorthand_syntax)
{
    ParserCompoundIdentifier name_p;
    ParserLiteralOrMap value_p;
    ParserToken s_eq(TokenType::Equals);
    ParserFunction function_p;

    ASTPtr node;
    String name;
    ASTPtr function_ast;
    bool have_eq = false;

    if (!name_p.parse(pos, node, expected))
        return false;

    have_eq = s_eq.ignore(pos, expected);

    if (!enable_shorthand_syntax && !have_eq)
        return false;

    tryGetIdentifierNameInto(node, name);

    /// Parameter
    if (name.starts_with(QUERY_PARAMETER_NAME_PREFIX))
    {
        if (!have_eq)
            return false;

        name = name.substr(strlen(QUERY_PARAMETER_NAME_PREFIX));

        if (name.empty())
            throw Exception(ErrorCodes::BAD_ARGUMENTS, "Parameter name cannot be empty");

        String value;

        if (!parseParameterValueIntoString(pos, value, expected))
            return false;

        parameter = {std::move(name), std::move(value)};
        return true;
    }

    if (have_eq)
    {
        /// Default
        if (ParserKeyword(Keyword::DEFAULT).ignore(pos, expected))
        {
            default_settings = name;
            return true;
        }

        /// Setting
        {
            auto pos_before_func = pos;
            if (function_p.parse(pos, function_ast, expected) && function_ast->as<ASTFunction>()->name == "disk")
            {
                change.name = name;
                change.value = createFieldFromAST(function_ast);

                return true;
            }
            pos = pos_before_func;
        }

        /// Query parameter as a setting value, e.g. `SET max_threads = {threads:UInt64}`
        /// or `SELECT ... SETTINGS max_threads = {threads:UInt64}`.
        /// Keep it as an ASTQueryParameter wrapped into a Field (same mechanism as disk(...) above);
        /// it is resolved later by ReplaceQueryParameterVisitor once parameter values are known.
        {
            ParserSubstitution substitution_p;
            ASTPtr substitution;
            if (substitution_p.parse(pos, substitution, expected))
            {
                change.name = name;
                change.value = createFieldFromAST(substitution);

                return true;
            }
        }

        if (!value_p.parse(pos, node, expected))
            return false;
    }
    else
    {
        /// A setting name with no value is shorthand for `= true`. Only a Bool setting can be
        /// written this way, but the parser does not know the settings schema, so it records that
        /// the value was omitted and leaves the check to `BaseSettings::applyChange`.
        node = make_intrusive<ASTLiteral>(Field(true));
    }

    change.name = name;
    change.value = node->as<ASTLiteral &>().value;
    change.shorthand = !have_eq;

    return true;
}

void Context::resetSettingsToDefaultValue(const std::vector<String> & names)
{
    if (names.empty())
        return;
    std::lock_guard lock(mutex);
    for (const String & name : names)
    {
        settings->setDefaultValue(name);
        /// `Settings` stores a `merge_tree_`-prefixed name as a custom setting, under the exact name that
        /// wrote it. Resetting one name of a setting therefore has to clear what its other names wrote.
        for (const auto & equivalent_name : settingEquivalentNames(name))
            settings->setDefaultValue(equivalent_name);
    }
    /// A setting nothing assigned holds what the active `compatibility` gives it.
    if ((*settings)[Setting::compatibility].value.empty())
        settings->resetSettingsChangedByCompatibility();
    else
    {
        settings->set(COMPATIBILITY_SETTING_NAME, (*settings)[Setting::compatibility].value);
        restrictSettingsChangedByCompatibilityWithLock(lock);
    }
    applySettingsQuirks(*settings);
    adjustSettingsForMakeDistributedPlan(*settings);
}
